	[TestMethod]
	public void TestKnownGood()
	{
		var clientDHNonce = BinaryHelper.ParseHexString("810878bc441eedcd4065f5d2775c5cbcae56ecef4a50ad8d0b76cd7814f68b56");
		var serverDHNonce = BinaryHelper.ParseHexString("02d9567049755ac10926ed48fe0e918890a6890a6c846c8e9a3191887d21a74f");

		var xa = new BigInteger(BinaryHelper.ParseHexString("8ed66343fa8fc11c9cc67c423c433b44bc429bee3851e64005f1d44967169365"), true, true);
		var p = new BigInteger(BinaryHelper.ParseHexString("00ffffffffffffffffc90fdaa22168c234c4c6628b80dc1cd129024e088a67cc74020bbea63b139b22514a08798e3404ddef9519b3cd3a431b302b0a6df25f14374fe1356d6d51c245e485b576625e7ec6f44c42e9a637ed6b0bff5cb6f406b7edee386bfb5a899fa5ae9f24117c4b1fe649286651ece65381ffffffffffffffff"), true, true);
		var yExpected = new BigInteger(BinaryHelper.ParseHexString("71d4125c8e3fc486d21bda188f70a75cb7de5f085c9dcdcc333ab738f1faa76fc6baed733e165a8936fbf336344cb88ba6fb94d12ddc9ac5b6b07838b210bf63a21d3864febc6d3cef2f03af6c0f1253b621d61e3cf8a2a19e969d320b82e980e065c22aa8a2dc1a5e15f751b4a14c9fdd6f864765533124f1100193269b380e"), true, true);
		var yb = new BigInteger(BinaryHelper.ParseHexString("00dff59a83eabe740c173676fbc9f60120aff1cbffe61da5109e23d0f49c970716f93b875e24b9549bf23d37d2105245ade2387705a65febb20dc3f58b079d17b730dbe426bf45140dd525b6bd8bb9a7ba640c4f9fa4bcd8615050779886adcd4a5d80d04b1a5e578518bf9c0ff6e06d381cf43a6f28afacf27a8d250cf43a9f03"), true, true);
		var zzExpected = new BigInteger(BinaryHelper.ParseHexString("26435b9425872920eb73f89b9ab24b4bb763bf784a06f3b8710f568bb304cdb58227320aec5359a508c5bca97ce10347cb1e18f681d1f2786ccff921001b5a24b1137fcc6f296dbccb4998512334fee8ea53f1c6aaaa157ff7e121d7ab7c75170973733613d259b5e15bce3eb0d4728fc58a8abf045b1ef059127345b6aa47c1"), true, true);
		var protokeyExpected = new BigInteger(BinaryHelper.ParseHexString("45d840293ce03fda033ede568f49bb935509e9aa1b0092355669423ec1ce779b"), true, true);

		var encAsrep = BinaryHelper.ParseHexString("");

		var group = new ModpGroup(p, 2);
		var dhkey = new ModpKeyPair(group, xa);

		Assert.AreEqual(yExpected, dhkey.PublicExponent);

		var zz = dhkey.CalculateAgreement(yb);
		Assert.AreEqual(zzExpected, zz);

		byte[] seed = new byte[32];
		byte[] expectedValue = BinaryHelper.ParseHexString("45d840293ce03fda033ede568f49bb935509e9aa1b0092355669423ec1ce779b");
		PreauthPkinitContext.DeriveKey(zz.ToByteArray(true, true), clientDHNonce, serverDHNonce, seed);

		CollectionAssert.AreEqual(expectedValue, seed);

		EncProfile_Aes256CtsHmacSha1_96 encProf = new EncProfile_Aes256CtsHmacSha1_96();
		var sessionKey = encProf.RandomToKey(seed);
		sessionKey.Decrypt(KeyUsage.AsrepEncPart, new KerberosV5Spec2.EncryptedData((int)encProf.EType, encAsrep));
	}

	[TestMethod]
	public void TestKnownBad()
	{
		var p = new BigInteger(BinaryHelper.ParseHexString(""), true, true);

		var clientDHNonce = BinaryHelper.ParseHexString("7f8d03535060717bdd9b101342de73d17d3dbf72789811ac92eb43c175f789b6");
		var xa = new BigInteger(BinaryHelper.ParseHexString(""), true, true);
		var yaExpected = new BigInteger(BinaryHelper.ParseHexString(""), true, true);

		var serverDHNonce = BinaryHelper.ParseHexString("f82da5e51887d02c48b9635ccfd029253f5f682c460921cec0a253ed874bf931");
		var yb = new BigInteger(BinaryHelper.ParseHexString(""), true, true);

		var zzExpected = new BigInteger(BinaryHelper.ParseHexString(""), true, true);
		var protokeyExpected = BinaryHelper.ParseHexString("d1bdc807c71f9e1eac3422aeb6d30c13e93c96b8e847e50e021369a6e740619e");

		var encAsrep = BinaryHelper.ParseHexString("");

		var group = new ModpGroup(p, 2);
		var dhkey = new ModpKeyPair(group, xa);

		Assert.AreEqual(yaExpected, dhkey.PublicExponent);

		var zz = dhkey.CalculateAgreement(yb);
		Assert.AreEqual(zzExpected, zz);

		byte[] seed = new byte[32];
		PreauthPkinitContext.DeriveKey(zz.ToByteArray(true, true), clientDHNonce, serverDHNonce, seed);
		CollectionAssert.AreEqual(protokeyExpected, seed);

		EncProfile_Aes256CtsHmacSha1_96 encProf = new EncProfile_Aes256CtsHmacSha1_96();
		var sessionKey = encProf.RandomToKey(seed);
		var encPart = Asn1DerDecoder.DecodeTlv<KerberosV5Spec2.EncASRepPart>(sessionKey.Decrypt(KeyUsage.AsrepEncPart, new KerberosV5Spec2.EncryptedData((int)encProf.EType, encAsrep)));
	}

