	private void TestKeyDerivation(byte[] input, byte[] expected)
	{
		byte[] seed = new byte[expected.Length];
		PreauthPkinitContext.DeriveKey(input, null, null, seed);
		CollectionAssert.AreEqual(expected, seed);
	}

	[TestMethod]
	public void TestKeyAgreement()
	{
		var group = new ModpGroup(
			new BigInteger(BinaryHelper.ParseHexString("B10B8F96A080E01DDE92DE5EAE5D54EC52C99FBCFB06A3C69A6A9DCA52D23B616073E28675A23D189838EF1E2EE652C013ECB4AEA906112324975C3CD49B83BFACCBDD7D90C4BD7098488E9C219A73724EFFD6FAE5644738FAA31A4FF55BCCC0A151AF5F0DC8B4BD45BF37DF365C1A65E68CFDA76D4DA708DF1FB2BC2E4A4371"), true, true),
			new BigInteger(BinaryHelper.ParseHexString("A4D1CBD5C3FD34126765A442EFB99905F8104DD258AC507FD6406CFF14266D31266FEA1E5C41564B777E690F5504F213160217B4B01B886A5E91547F9E2749F4D7FBD7D3B9A92EE1909D0D2263F80A76A6A24C087A091F531DBF0A0169B6A28AD662A4D18E73AFA32D779D5918D08BC8858F4DCEF97C2A24855E6EEB22B3B2E5"), true, true)
			);

		BigInteger xa = new BigInteger(BinaryHelper.ParseHexString("B9A3B3AE8FEFC1A2930496507086F8455D48943E"), true, true);
		BigInteger ya = new BigInteger(BinaryHelper.ParseHexString("2A853B3D92197501B9015B2DEB3ED84F5E021DCC3E52F109D3273D2B7521281CBABE0E76FF5727FA8ACCE26956BA9A1FCA26F20228D8693FEB10841D84A7360054ECE5A7F5B7A61AD3DFB3C60D2E43106D8727DA37DF9CCE95B478755D06BCEA8F9D45965F75A5F3D1DF3701165FC9E50C4279CEB07F989540AE96D5D88ED776"), true, true);
		BigInteger xb = new BigInteger(BinaryHelper.ParseHexString("9392C9F9EB6A7A6A9022F7D83E7223C6835BBDDA"), true, true);
		BigInteger yb = new BigInteger(BinaryHelper.ParseHexString("717A6CB053371FF4A3B932941C1E5663F861A1D6AD34AE66576DFB98F6C6CBF9DDD5A56C7833F6BCFDFF095582AD868E440E8D09FD769E3CECCDC3D3B1E4CFA057776CAAF9739B6A9FEE8E7411F8D6DAC09D6A4EDB46CC2B5D5203090EAE6126311E53FD2C14B574E6A3109A3DA1BE41BDCEAA186F5CE06716A2B6A07B3C33FE"), true, true);
		BigInteger expected = new BigInteger(BinaryHelper.ParseHexString("5C804F454D30D9C4DF85271F93528C91DF6B48AB5F80B3B59CAAC1B28F8ACBA9CD3E39F3CB614525D9521D2E644C53B807B810F340062F257D7D6FBFE8D5E8F072E9B6E9AFDA9413EAFB2E8B0699B1FB5A0CACEDDEAEAD7E9CFBB36AE2B420835BD83A19FB0B5E96BF8FA4D09E345525167ECD9155416F46F408ED31B63C6E6D"), true, true);


		ModpKeyPair mykey = new ModpKeyPair(group, xa);
		Assert.AreEqual(mykey.PublicExponent, ya);
		ModpKeyPair yourkey = new ModpKeyPair(group, xb);
		Assert.AreEqual(yourkey.PublicExponent, yb);

		var actualA = mykey.CalculateAgreement(yb);
		var actualB = yourkey.CalculateAgreement(ya);
		Assert.AreEqual(actualA, actualB);
		Assert.AreEqual(expected, actualB);
	}

